-- Find Support directory, round 3 (2026-10-28): the 38 countries with no
-- listing were searched again. Two providers could be confirmed on their own
-- website or an official directory (source_url); everything else found was
-- news-only and stays a lead in docs/DIRECTORY_COVERAGE.md.

insert into public.resources (name, category, country, region, city, address, location, age_min, age_max, services, curriculum, class_size_avg, provider_type, languages, conditions, contact_info, url, description, source_url, verified, last_verified_at, is_published)
select 'Autism Association of Namibia (AAN)', 'support_group', 'Namibia', 'Khomas', 'Windhoek', 'Gareth Building (2nd floor), 44 TV More Street, Windhoek 10012', 'Windhoek, Khomas', null, null, array['support_group', 'parent_training']::text[], '{}'::text[], null, 'ngo', '{}'::text[], array['Autism']::text[], '{"phone":"+264 81 346 5912","email":"autnam@iway.na","website":"http://www.autism-namibia.org"}'::jsonb, 'http://www.autism-namibia.org', 'Volunteer-run national association of parents, autistic people and professionals. Offers support and training on autism for parents and professionals, and is raising funds for an assessment and support centre. Details confirmed through Namibia''s Civic+264 civil-society directory.', 'https://www.civic264.org.na/disabilities/aan', true, '2026-10-28', true
where not exists (select 1 from public.resources where name = 'Autism Association of Namibia (AAN)');

insert into public.resources (name, category, country, region, city, address, location, age_min, age_max, services, curriculum, class_size_avg, provider_type, languages, conditions, contact_info, url, description, source_url, verified, last_verified_at, is_published)
select 'Manzini Autism Respite Centre', 'therapist', 'Eswatini', 'Manzini', 'Manzini', 'Althea Road, Fairview South Township, Manzini', 'Manzini', 3, 13, array['speech_therapy', 'occupational_therapy', 'physiotherapy']::text[], '{}'::text[], null, 'public', '{}'::text[], array['Autism', 'Learning differences']::text[], '{"phone":"+268 2508 5105","email":"lindiwe.dlamini@manzinicity.co.sz"}'::jsonb, 'https://manzinicity.co.sz/manzini-municipality-reaffirms-commitment-to-autism-response/', 'Municipal centre for autistic children aged 3 to 13, also seeing children with communication, physical or learning difficulties. Speech and occupational therapy, plus physiotherapy on Mondays, Wednesdays and Fridays, 8am to 4pm (E200 first assessment, E100 per follow-up, as of April 2025).', 'https://manzinicity.co.sz/manzini-municipality-reaffirms-commitment-to-autism-response/', true, '2026-10-28', true
where not exists (select 1 from public.resources where name = 'Manzini Autism Respite Centre');
